class Solution {
private:
  bool rule_row[N][N] = {false};
  bool rule_col[N][N] = {false};
  bool rule_box[N][N] = {false};

  unsigned int left_num = 81;

  void sudoku_rule(vector<vector<char>> board) {
    for (int i = 0; i < N; i++) { // row rule
      for (int j = 0; j < N; j++) {
        int num = board[i][j] - 49;
        if (num >= 0) {
          rule_row[i][num] = true;
          left_num--;
        }
      }
    }
    for (int i = 0; i < N; i++) { // column rule
      for (int j = 0; j < N; j++) {
        int num = board[j][i] - 49;
        if (num >= 0) {
          rule_col[i][num] = true;
        }
      }
    }
    for (int i = 0; i < N; i++) { // box rule
      for (int j = 0; j < N; j++) {
        int num = board[i / M * M + j / M][(i % M) * M + j % M] - 49;
        if (num >= 0) {
          rule_box[i][num] = true;
        }
      }
    }
  }

  void sudoku_rule_cell(vector<vector<char>> board, int row, int col, vector<bool> &poss) {
    if (board[row][col] != '.') {
      poss = {true, true, true, true, true, true, true, true, true};
      return;
    }
    int box = row / M * M + col / M;
    for (int i = 0; i < N; i++) {
      if (rule_row[row][i]) {
        poss[i] = true;
      }
      if (rule_col[col][i]) {
        poss[i] = true;
      }
      if (rule_box[box][i]) {
        poss[i] = true;
      }
    }
  }

  void sudoku_set_cell(vector<vector<char>> &board, int row, int col, char val) {
    board[row][col] = val;

    rule_row[row][val - 49] = true;
    rule_col[col][val - 49] = true;

    rule_box[row / M * M + col / M][val - 49] = true;

    left_num--;
  }

  void sudoku_erase_cell(vector<vector<char>> &board, int row, int col) {
    char val = board[row][col];

    rule_row[row][val - 49] = false;
    rule_col[col][val - 49] = false;

    rule_box[row / M * M + col / M][val - 49] = false;

    board[row][col] = '.';
    left_num++;
  }

  int cell_poss_num(vector<bool> &poss) {
    int result = 0;
    for (int i = 0; i < N; i++) {
      if (!poss[i]) {
        result++;
      }
    }
    return result;
  }

  void sudoku_get_less_poss(vector<vector<char>> &board, int *row, int *col, vector<bool> &poss) {
    int poss_num = 9;
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < N; j++) {
        vector<bool> temp(N, false);
        sudoku_rule_cell(board, i, j, temp);
        int p = cell_poss_num(temp);
        if (p != 0 && p < poss_num) {
          poss_num = p;
          *row     = i;
          *col     = j;
          poss     = temp;
        }
      }
    }
  }

public:
  void solveSudoku(vector<vector<char>> &board) {
    sudoku_rule(board);
    solve(board);
    return;
  }

  bool solve(vector<vector<char>> &board) {
    if (left_num == 0) {
      return true;
    }
    int row = 0;
    int col = 0;

    vector<bool> poss(N, false);
    sudoku_get_less_poss(board, &row, &col, poss);

    if (board[row][col] != '.') {
      return false;
    }

    bool found_solution = false;
    for (int i = 0; i < N; i++) {
      if (!poss[i]) {
        sudoku_set_cell(board, row, col, (char)(i + 49));
        if ((found_solution = solve(board))) {
          break;
        }
        sudoku_erase_cell(board, row, col);
      }
    }
    return found_solution;
  }
};

func solveSudoku(board [][]byte) {
	var rows, cols, boxes [9][9]bool
	var empties [][2]int
	for i := 0; i < 9; i++ {
		for j := 0; j < 9; j++ {
			if board[i][j] == '.' {
				empties = append(empties, [2]int{i, j})
			} else {
				d := board[i][j] - '1'
				rows[i][d] = true
				cols[j][d] = true
				boxes[i/3*3+j/3][d] = true
			}
		}
	}
	var solve func(idx int) bool
	solve = func(idx int) bool {
		if idx == len(empties) {
			return true
		}
		i, j := empties[idx][0], empties[idx][1]
		b := i/3*3 + j/3
		for d := byte(0); d < 9; d++ {
			if !rows[i][d] && !cols[j][d] && !boxes[b][d] {
				board[i][j] = d + '1'
				rows[i][d], cols[j][d], boxes[b][d] = true, true, true
				if solve(idx + 1) {
					return true
				}
				rows[i][d], cols[j][d], boxes[b][d] = false, false, false
				board[i][j] = '.'
			}
		}
		return false
	}
	solve(0)
}

class Solution {
  private boolean[][] rows = new boolean[9][9];
  private boolean[][] cols = new boolean[9][9];
  private boolean[][] boxes = new boolean[9][9];
  private int[] emptyI = new int[81];
  private int[] emptyJ = new int[81];
  private int empties = 0;

  public void solveSudoku(char[][] board) {
    for (int i = 0; i < 9; i++) {
      for (int j = 0; j < 9; j++) {
        char c = board[i][j];
        if (c == '.') {
          emptyI[empties] = i;
          emptyJ[empties] = j;
          empties++;
        } else {
          int d = c - '1';
          rows[i][d] = cols[j][d] = boxes[(i / 3) * 3 + j / 3][d] = true;
        }
      }
    }
    solve(board, 0);
  }

  private boolean solve(char[][] board, int idx) {
    if (idx == empties) {
      return true;
    }
    int i = emptyI[idx], j = emptyJ[idx];
    int b = (i / 3) * 3 + j / 3;
    for (int d = 0; d < 9; d++) {
      if (!rows[i][d] && !cols[j][d] && !boxes[b][d]) {
        board[i][j] = (char) ('1' + d);
        rows[i][d] = cols[j][d] = boxes[b][d] = true;
        if (solve(board, idx + 1)) {
          return true;
        }
        rows[i][d] = cols[j][d] = boxes[b][d] = false;
        board[i][j] = '.';
      }
    }
    return false;
  }
}

class Solution:
    def solveSudoku(self, board: List[List[str]]) -> None:
        rows = [[False] * 9 for _ in range(9)]
        cols = [[False] * 9 for _ in range(9)]
        boxes = [[False] * 9 for _ in range(9)]
        empties = []
        for i in range(9):
            for j in range(9):
                c = board[i][j]
                if c == ".":
                    empties.append((i, j))
                else:
                    d = ord(c) - ord("1")
                    rows[i][d] = cols[j][d] = boxes[(i // 3) * 3 + j // 3][d] = True

        def solve(idx: int) -> bool:
            if idx == len(empties):
                return True
            i, j = empties[idx]
            b = (i // 3) * 3 + j // 3
            for d in range(9):
                if not rows[i][d] and not cols[j][d] and not boxes[b][d]:
                    board[i][j] = chr(ord("1") + d)
                    rows[i][d] = cols[j][d] = boxes[b][d] = True
                    if solve(idx + 1):
                        return True
                    rows[i][d] = cols[j][d] = boxes[b][d] = False
                    board[i][j] = "."
            return False

        solve(0)

impl Solution {
    pub fn solve_sudoku(_board: &mut Vec<Vec<char>>) {}
}

const solveSudoku = (board: string[][]): void => {
  const rows: boolean[][] = Array.from({ length: 9 }, () => new Array(9).fill(false));
  const cols: boolean[][] = Array.from({ length: 9 }, () => new Array(9).fill(false));
  const boxes: boolean[][] = Array.from({ length: 9 }, () => new Array(9).fill(false));
  const empties: [number, number][] = [];
  for (let i = 0; i < 9; i++) {
    for (let j = 0; j < 9; j++) {
      const c = board[i][j];
      if (c === '.') {
        empties.push([i, j]);
      } else {
        const d = c.charCodeAt(0) - '1'.charCodeAt(0);
        rows[i][d] = cols[j][d] = boxes[Math.floor(i / 3) * 3 + Math.floor(j / 3)][d] = true;
      }
    }
  }

  const solve = (idx: number): boolean => {
    if (idx === empties.length) return true;
    const [i, j] = empties[idx];
    const b = Math.floor(i / 3) * 3 + Math.floor(j / 3);
    for (let d = 0; d < 9; d++) {
      if (!rows[i][d] && !cols[j][d] && !boxes[b][d]) {
        board[i][j] = String.fromCharCode('1'.charCodeAt(0) + d);
        rows[i][d] = cols[j][d] = boxes[b][d] = true;
        if (solve(idx + 1)) return true;
        rows[i][d] = cols[j][d] = boxes[b][d] = false;
        board[i][j] = '.';
      }
    }
    return false;
  };

  solve(0);
};
